From 4cc07419e57ad4ebdabdc76cdafe6e305f5b752f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:00:49 +0100
Subject: [PATCH] kcm: add an option to not switch to newly connected devices
 on PipeWire

WirePlumber always made a newly connected device the default when none
was chosen, and the KCM had no way to turn this off. When the new option
is unchecked, the current default is kept configured instead.

BUG: 516683
---
 src/globalconfig.kcfg              |  4 ++++
 src/kcm/ui/main.qml                | 18 +++++++++++++++---
 src/kded/audioshortcutsservice.cpp | 30 ++++++++++++++++++++++++++++++
 src/kded/audioshortcutsservice.h   |  2 ++
 4 files changed, 51 insertions(+), 3 deletions(-)

diff --git a/src/globalconfig.kcfg b/src/globalconfig.kcfg
index 29dd8626..a252ef7d 100644
--- a/src/globalconfig.kcfg
+++ b/src/globalconfig.kcfg
@@ -46,6 +46,10 @@
             <label>Show OSD when changing default output device.</label>
             <default>true</default>
         </entry>
+        <entry name="AutoSwitchToNewDevices" type="Bool">
+            <label>Automatically switch to newly connected devices.</label>
+            <default>true</default>
+        </entry>
         <entry name="GlobalMuteSinks" type="Bool">
             <label>Mute all audio.</label>
             <default>false</default>
diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 140954d7..405f1bc7 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -89,25 +89,37 @@ KCM.ScrollViewKCM {
         },
         Kirigami.Action {
             id: configureButton
-            visible: moduleManager.settingsSupported
-            enabled: moduleManager.configModuleLoaded
+            visible: moduleManager.settingsSupported || Server.hasWirePlumber
+            enabled: !moduleManager.settingsSupported || moduleManager.configModuleLoaded
             text: i18nd("kcm_pulseaudio", "Configure…")
             icon.name: "configure"

-            tooltip: i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName)
+            tooltip: moduleManager.settingsSupported ? i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName) : ""

             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Add virtual output device for simultaneous output on all local sound cards")
                 checkable: true
                 checked: moduleManager.combineSinks
                 onToggled: moduleManager.combineSinks = checked
             }
             Kirigami.Action {
+                visible: moduleManager.settingsSupported
                 text: i18nd("kcm_pulseaudio", "Automatically switch all running streams when a new output becomes available")
                 checkable: true
                 checked: moduleManager.switchOnConnect
                 onToggled: moduleManager.switchOnConnect = checked
             }
+            Kirigami.Action {
+                visible: !moduleManager.settingsSupported
+                text: i18nd("kcm_pulseaudio", "Automatically switch to newly connected devices")
+                checkable: true
+                checked: config.autoSwitchToNewDevices
+                onToggled: {
+                    config.autoSwitchToNewDevices = checked
+                    config.save()
+                }
+            }
         }
     ]

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..fb9ae0e2 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -54,6 +54,12 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
     }

     connect(PulseAudioQt::Context::instance()->server(), &PulseAudioQt::Server::defaultSinkChanged, this, &AudioShortcutsService::handleDefaultSinkChange);
+    connect(PulseAudioQt::Context::instance()->server(), &PulseAudioQt::Server::defaultSinkChanged, this, &AudioShortcutsService::keepDefaultSink);
+    connect(PulseAudioQt::Context::instance()->server(), &PulseAudioQt::Server::defaultSourceChanged, this, &AudioShortcutsService::keepDefaultSource);
+    connect(m_globalConfig, &GlobalConfig::AutoSwitchToNewDevicesChanged, this, [this]() {
+        keepDefaultSink();
+        keepDefaultSource();
+    });
     connect(PulseAudioQt::Context::instance(), &PulseAudioQt::Context::stateChanged, this, &AudioShortcutsService::contextConnectedChanged);
     connect(PulseAudioQt::Context::instance(), &PulseAudioQt::Context::autoConnectingChanged, this, &AudioShortcutsService::contextAutoConnectingChanged);
     connect(&m_preferredDevice, &PreferredDevice::sinkChanged, this, [this]() {
@@ -245,6 +251,30 @@ int AudioShortcutsService::changeVolumePercent(PulseAudioQt::Device *device, int
     return newPercent;
 }

+// WirePlumber only moves away from the configured default device when it is removed, so configuring the
+// current default keeps newly connected devices from taking over
+void AudioShortcutsService::keepDefaultSink()
+{
+    auto server = PulseAudioQt::Context::instance()->server();
+    if (m_globalConfig->autoSwitchToNewDevices() || !server->isPipeWire()) {
+        return;
+    }
+    if (auto sink = server->defaultSink(); sink && sink->name() != DUMMY_OUTPUT_NAME) {
+        server->setDefaultSink(sink);
+    }
+}
+
+void AudioShortcutsService::keepDefaultSource()
+{
+    auto server = PulseAudioQt::Context::instance()->server();
+    if (m_globalConfig->autoSwitchToNewDevices() || !server->isPipeWire()) {
+        return;
+    }
+    if (auto source = server->defaultSource(); source && !source->name().startsWith(DUMMY_OUTPUT_NAME)) {
+        server->setDefaultSource(source);
+    }
+}
+
 void AudioShortcutsService::handleDefaultSinkChange()
 {
     const PulseAudioQt::Sink *defaultSink = PulseAudioQt::Context::instance()->server()->defaultSink();
diff --git a/src/kded/audioshortcutsservice.h b/src/kded/audioshortcutsservice.h
index 26cf38d8..ec864e14 100644
--- a/src/kded/audioshortcutsservice.h
+++ b/src/kded/audioshortcutsservice.h
@@ -55,6 +55,8 @@ private:
     static int volumePercent(qint64 volume);
     int changeVolumePercent(PulseAudioQt::Device *device, int deltaPercent);
     void handleDefaultSinkChange();
+    void keepDefaultSink();
+    void keepDefaultSource();
     void muteVolume();
     void playFeedback(int sinkIdx);
     void showMute(int percent);
